    masterDataSearchByField(fieldModel: any) {
      try {
        const field_name = fieldModel.name;
        const config = this.lookup_configurations.get(field_name);

        if (!config) {
          logError('field vardef is missing for master loopup', field_name);
          return;
        }

        const id = uid();
        this.ms_advance_filters[id] = {
          fuzzy_field: config.lookup_field.toLowerCase(),
          search_text: this.formBuilderModel[field_name].formatted_value,
          field_name,
          primary: true,
        };
        this.master_lookup_type = config.lookup_name;

        this.ms_view_model = this.formBuilderConfigModel;
        this.master_data_fields_map = new Map();
        this.master_data_fields_map.set(this.master_lookup_type, config);
        this.master_data_popup_width = this.calculateWidthForMSPopuup();

        // primary fields
        if (config.parent_field_id && config.parent_field_id != '') {
          let parent_field = null;
          for (const [index, field] of config.fields.entries()) {
            if (config.parent_field_id == field.field_id) {
              parent_field = field;
              break;
            }
          }

          if (parent_field) {
            const id = uid();
            this.ms_advance_filters[id] = {
              fuzzy_field: parent_field.lookup_field.toLowerCase(),
              search_text:
                this.formBuilderModel[parent_field.field_name].formatted_value,
              field_name: parent_field.field_name,
              primary: false,
            };
          }
        }

        this.fuzzyDialog = true;
      } catch (error) {
        logError(error);
      }
    },

    closeMsDialog() {
      this.fuzzyDialog = false;
      this.ms_advance_filters = {};
    },

    calculateWidthForMSPopuup() {
      let default_width = '700';
      const main_el = document.querySelector(
        '.field_validation',
      ) as HTMLElement;
      if (!main_el) {
        return default_width;
      }

      const fields_area_el = document.querySelector(
        '#field_scrolle',
      ) as HTMLElement;
      if (!fields_area_el) {
        return default_width;
      }

      const calculated_width = fields_area_el.offsetWidth;
      if (calculated_width <= 0) {
        return default_width;
      }
      return String(calculated_width);
    },

    windowResize() {
      if (this.fuzzyDialog) {
        this.master_data_popup_width = this.calculateWidthForMSPopuup();
      }
    },

