    updateFieldInFormBuilder(
      fieldElement: HTMLElement,
      getTextApiResponse: any,
    ) {
      let inputEl: HTMLInputElement | null = fieldElement.querySelector(
        '.' + this.connectionId + '_input',
      );
      if (!inputEl) {
        return;
      }

      const event = new CustomEvent('update_field_value', {
        detail: {
          input_class: this.connectionId + '_input',
          val: getTextApiResponse.formatted_value,
        },
      });
      inputEl.dispatchEvent(event);
    },

    updateFieldData(getTextApiResponse: any) {
      // Field that don't have a box, and you draw a box against them, you should set attribute of page number to that field
      let fieldElement: HTMLElement | null = $('#' + this.connectionId);
      fieldElement!.setAttribute('pageno', this.page.toString());

      if (fieldElement) {
        this.updateFieldInFormBuilder(fieldElement, getTextApiResponse);
      }

      const componentType = this.getInputType(fieldElement as HTMLElement);

      this.formBuilderModel[this.connectionId].value = getTextApiResponse.value;
      this.formBuilderModel[this.connectionId].formatted_value =
        getTextApiResponse.formatted_value;
      this.formBuilderModel[this.connectionId].content =
        getTextApiResponse.text;
      this.formBuilderModel[this.connectionId].api_save = true;
      this.formBuilderModel[this.connectionId].score_description = '';

      if (componentType === 'checkbox') {
        this.formBuilderModel[this.connectionId].value = false;
        this.formBuilderModel[this.connectionId].formatted_value = false;
        this.formBuilderModel[this.connectionId].content = false;

        if (
          getTextApiResponse.formatted_value &&
          getTextApiResponse.formatted_value.toLowerCase() === 'x'
        ) {
          this.handleSingleSelection(this.connectionId);

          this.formBuilderModel[this.connectionId].value = true;
          this.formBuilderModel[this.connectionId].content = true;
          this.formBuilderModel[this.connectionId].formatted_value = true;
        }
      }

      // Field that don't have a box, and you draw a box against them, you should also set the value of this input in apiData
      // This would help us when we navigates between pages
      this.valueChangesOnRedraw(
        this.connectionId,
        getTextApiResponse.coords,
        this.page,
      );
      // this.enableOrDisableExportButton();

      this.$forceUpdate();
    },
    valueChangesOnRedraw(
      connectionId: string,
      coordinates?: any,
      page?: number,
    ) {
      let singleSelectionFields = [
        'stuck_checkbox',
        'paar_checkbox',
        'hose_checkbox',
      ];
      let fields_to_update: string[] = [];

      if (singleSelectionFields.includes(connectionId)) {
        fields_to_update = singleSelectionFields;
      } else {
        fields_to_update.push(connectionId);
      }

      if (coordinates && page) {
        this.prepareImportJson(fields_to_update, coordinates, page, 'AI');
      } else {
        this.prepareImportJson(fields_to_update);
      }

      this.$emit('removeOldMapiingsAndDrawNew', connectionId);

      this.$forceUpdate();
    },
    prepareImportJson(
      fields_to_update: string[],
      coordinates?: any,
      page?: number,
      extractionMethod?: string,
    ) {
      fields_to_update.forEach((connection_id: string) => {
        this.updateImportJson(
          connection_id,
          coordinates,
          page,
          extractionMethod,
        );
      });
    },

    updateImportJson(
      connectionId: string,
      coordinates?: any,
      page?: number,
      extractionMethod?: string,
    ) {
      let found = false;
      const recordFields = Array.isArray(this.record?.fields)
        ? this.record.fields
        : [];
      recordFields.forEach(async (value: any) => {
        if (value.name === connectionId) {
          found = true;

          if (!value.hasOwnProperty('original')) {
            value['original'] = Object.assign(
              {},
              JSON.parse(JSON.stringify(value)),
            );
          }

          if (!value.hasOwnProperty('original_value')) {
            value['original_value'] = value.value;
          }

          if (coordinates) {
            value.coords = coordinates;
          }
          if (page) {
            value.page = page;
          }

          value.is_valid = true;
          value.is_validated = true;

          let field = this.formBuilderModel[connectionId];
          if (!field) {
            return;
          }
          value.formatted_value = field.formatted_value;
          value.value = field.formatted_value;
          value.content = field.formatted_value;

          if (!(field.hasOwnProperty('api_save') && field.api_save)) {
            value.value = field.formatted_value;
          }

          const localeObj = (this.record.amount_format_locale || 'en_US').split(
            '.',
          );
          if (
            !(field.hasOwnProperty('api_save') && field.api_save) &&
            this.conversionFields.includes(field.name) &&
            localeObj[0] != 'en_US'
          ) {
            value.value = await this.convertValueAccordingToLocale(
              value.value,
              localeObj[0],
              'en_US',
            );
            value.float_value = +value.value;
          }

          value.color = 'success-border-left';
          if (value.extraction_method == 'MD') {
            value.color = 'extraction_method-border-left';
          }

          if (
            value.is_required &&
            (value.formatted_value == '' || value.formatted_value == null)
          ) {
            value.color = 'error-border-left';
          }

          // value.confidence = 0.99;
          return;
        }
      });
      if (!found) {
        if (!Array.isArray(this.record.fields)) {
          this.record.fields = [];
        }
        if (!this.formBuilderModel[connectionId]) {
          return;
        }
        this.record.fields.push({});

        const field_index = this.record.fields.length - 1;
        this.record.fields[field_index].name = connectionId;
        this.record.fields[field_index].content =
          this.formBuilderModel[connectionId].content;
        // this.record.fields[this.record.fields.length - 1].confidence = 0.99;
        this.record.fields[field_index].formatted_value =
          this.formBuilderModel[connectionId].formatted_value;
        this.record.fields[field_index].value =
          this.formBuilderModel[connectionId].value;
        this.record.fields[field_index].original_value = '';
        this.record.fields[field_index].validation_code = '';
        this.record.fields[field_index].extraction_method = extractionMethod;
        this.record.fields[field_index].is_validated = true;
        this.record.fields[field_index].is_valid = true;
        this.record.fields[field_index].color = 'success-border-left';

        if (coordinates) {
          this.record.fields[field_index].coords = coordinates;
        }

        if (page) {
          this.record.fields[field_index].page = page;
        }
      }
    },
    initTempFieldDelete() {
      if (!Array.isArray(this.record?.fields)) {
        return;
      }
      this.record.fields.forEach((value: any, index: any) => {
        if (value.name === this.connectionId) {
          if (!value.hasOwnProperty('original')) {
            value['original'] = Object.assign(
              {},
              JSON.parse(JSON.stringify(value)),
            );
          }

          const update_attr = {
            color: null,
            coords: null,
            confidence: 0,
            validation_code: null,
          };

          this.formBuilderModel[this.connectionId] = Object.assign(
            this.formBuilderModel[this.connectionId],
            update_attr,
          );
          this.record.fields[index] = Object.assign(
            this.record.fields[index],
            update_attr,
          );
        }
      });
    },

