    getElementBorder(element: any) {
      let border = '';
      if (this.formBuilderConfigModel.hasOwnProperty(element.name)) {
        border = this.formBuilderConfigModel[element.name].right_border
          ? ' border-right'
          : '';

        border += this.formBuilderConfigModel[element.name].bottom_border
          ? ' border-bottom'
          : '';

        return border;
      }

      border = element.right_border ? ' border-right' : '';

      border += element.bottom_border ? ' border-bottom' : '';

      return border;
    },

