    },

    isFieldScriptCalculated(field_name: string) {
      if (
        this.formBuilderConfigModel[field_name].hasOwnProperty(
          'run_script_on_change',
        ) &&
        this.formBuilderConfigModel[field_name].run_script_on_change === true
      ) {
        return true;
      }

      return false;
    },

    isFieldhasWorkflowEnabled(field_name: string) {
      if (
        this.formBuilderConfigModel[field_name].hasOwnProperty(
          'run_workflow_on_change',
        ) &&
        this.formBuilderConfigModel[field_name].run_workflow_on_change === true
      ) {
        return true;
      }

      return false;
    },

    handleScriptCalculatedFields(field_name: string) {
      try {
        if (!this.isFieldScriptCalculated(field_name)) {
          return;
        }
        this.record.apply_script_triggered_on_field = field_name;
        //
        logError(
          'handleScriptCalculatedFields',
          field_name,
          this.formBuilderModel[field_name].formatted_value,
        );
        this.createNewScriptRequest();
      } catch (err) {
        logError(err);
      } finally {
      }
    },

    handleScriptForNonCalcField() {
      if (
        this.api_request_id !== '' &&
        this.record.hasOwnProperty('apply_script_triggered_on_field') &&
        this.record.apply_script_triggered_on_field
      ) {
        logError(
          'handleScriptForNonCalcField',
          this.api_request_id,
          this.record.apply_script_triggered_on_field,
        );
        this.updateScriptRequest();
        this.createNewScriptRequest();
      }
    },

    scriptCalculateFuncWrapper(e: any) {
      let row_id = '';
      let column_name = '';
      if (e.detail.columnName) {
        column_name = e.detail.columnName;
      }
      if (e.detail.rowId) {
        row_id = e.detail.rowId;
      }
      this.record.apply_script_triggered_on_table_row = row_id;
      this.record.apply_script_triggered_on_table_field = column_name;
      this.debounceScriptCalculateFunc();
    },

    async applyScript(showLoading = false) {
      try {
        if (showLoading) {
          this.script_loading = true;
        }
        this.auto_saved_done = false;
        this.auto_saving = true;
        this.script_api_timestamp = Date.now();
        const is_done = await this.applyScriptOnDocument();
        if (!is_done) {
          return;
        }

        let discard_response = false;

        for (const [field_name, fieldDef] of Object.entries(
          this.formBuilderModel,
        )) {
          let field_timestamp = 0;
          const field = fieldDef as any;
          if (field.hasOwnProperty('update_timestamp')) {
            field_timestamp = field.update_timestamp;
          }
          if (field_timestamp > this.script_api_timestamp) {
            discard_response = true;
          }

          if (discard_response) {
            logInfo(
              'discard_response',
              field_name,
              field.formatted_value,
              field_timestamp,
              this.script_api_timestamp,
            );
          }
        }

        if (discard_response) {
          this.updateRequestId();
          this.createNewScriptRequest();
          return;
        }

        await this.updateRecordAfterScript();

        this.$emit('setDocVersion');
        this.setDataToCache();

        this.highlightFieldsMode = true;
        await this.makeModel();

        const event = new CustomEvent('prepare_rows', {});
        document.dispatchEvent(event);
      } catch (err) {
        logError(err);
      } finally {
        this.auto_saving = false;
        this.auto_saved_done = true;
        this.script_loading = false;
        setTimeout(() => {
          this.auto_saved_done = false;
        }, 10000);
      }
    },

    async rejectDocument() {
      try {
        if (this.isReadOnly) {
          return;
        }
        this.showLoading();
        await this.saveData();
        const data = { request_type: 'reject' };
        const response = await documentDetailApiService.rejectDocument(
          data,
          this.docId,
        );
        if (response.success === false) {
          throw response.message;
        }

        notify.success(this.$t('MSG_SAVE'));
        if (response.success === true) {
          this.routeToDashboard();
          return;
        }
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    populateMasterDataFields() {
      try {
        this.closeMsDialog();
        this.showLoading();

        let jsonResponse = JSON.parse(this.master_data_row);
        const config = this.master_data_fields_map.get(this.master_lookup_type);
        const lookup_fields = config.fields;

        let fields_to_update = [] as string[];
        for (let [index, field] of lookup_fields.entries()) {
          const field_name = field.field_name;
          const lookup_field = field.lookup_field.toLowerCase();

          if (
            jsonResponse.hasOwnProperty(lookup_field) &&
            this.formBuilderModel.hasOwnProperty(field_name)
          ) {
            this.formBuilderModel[field_name].formatted_value =
              jsonResponse[lookup_field];
            this.formBuilderModel[field_name].value =
              jsonResponse[lookup_field];
            this.formBuilderModel[field_name].color =
              'extraction_method-border-left';
            this.formBuilderModel[field_name].extraction_method = 'MD';

            if (
              !this.isCurrentFieldPrimary(field_name) &&
              this.isContentChanged(
                this.formBuilderModel[field_name].content,
                jsonResponse[lookup_field],
              )
            ) {
              this.formBuilderModel[field_name].content =
                jsonResponse[lookup_field];
              this.formBuilderModel[field_name].coords = null;
              this.formBuilderModel[field_name].confidence = 0;
              this.formBuilderModel[field_name].validation_code = null;
            }

            fields_to_update.push(field_name);
          }
        }

        if (fields_to_update.length > 0) {
          this.prepareImportJson(fields_to_update, [], this.page, 'MD');
        }
        this.resetMasterDataStore();
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    jumpToTable(event: any) {
      event.preventDefault();
      for (const [index, group] of this.formLayout.entries()) {
        if (!this.isGroupTable(index)) {
          continue;
        }
        this.focusOnTableGroup(index);
        break;
      }
    },

    triggerTableAddRow(event: any) {
      for (const [index, group] of this.formLayout.entries()) {
        if (!this.isGroupTable(index)) {
          continue;
        }

        const field = this.formLayout[index].rows[0];
        let fieldEl: HTMLElement | null = document!.querySelector(
          '.' + field.name,
        );
        if (!fieldEl) {
          return;
        }
        const event = new CustomEvent('trigger_add_row', { detail: {} });
        fieldEl.dispatchEvent(event);
        break;
      }
      event.preventDefault();
    },

    findGroupShortcutkey(event: any) {
      const key = event.key;
      const combKey_list = ['shift', 'alt'];

      const comb_key = combKey_list.find((comb_key: any) => {
        const mapIndex = comb_key + key;
        return this.groupShortCutMap.has(mapIndex);
      });
      return comb_key;
    },

    focusOnGroupFromMap(event: any) {
      if (this.groupShortCutMap.size === 0) {
        return;
      }

      const comb_key = this.findGroupShortcutkey(event);
      if (!comb_key) {
        return;
      }

      const mapIndex = comb_key + event.key;
      const groupIndex = this.groupShortCutMap.get(mapIndex);
      if (
        groupIndex === null ||
        groupIndex === undefined ||
        groupIndex === ''
      ) {
        return;
      }
      event.preventDefault();
      this.focusGroup(groupIndex, event);
    },

    isGroupTable(groupIndex: string) {
      if (!this.formLayout[groupIndex].rows[0]) {
        return false;
      }
      return this.formLayout[groupIndex].rows[0].fieldType === 'ExtractedTable';
    },

    focusGroup(groupIndex: string, event: any) {
      event.preventDefault();
      if (this.formLayout[groupIndex].rows.length === 0) {
        return;
      }

      if (this.isGroupTable(groupIndex)) {
        this.focusOnTableGroup(groupIndex);
        return;
      }

      const field_name = this.getFirstFieldOfGroup(groupIndex);
      if (!field_name) {
        return;
      }
      this.focusOnField(field_name);
    },

    getFirstFieldOfGroup(groupIndex: string) {
      let field_name = '';
      let exclude_field_types = ['CheckBox', 'TableOfCheckboxes'];
      exclude_field_types = exclude_field_types.concat(
        this.excluded_field_types,
      );

      const firstElement = this.formLayout[groupIndex].rows.find((row: any) => {
        return !exclude_field_types.includes(row.fieldType);
      });

      if (!firstElement) {
        return field_name;
      }

      field_name = firstElement.name;
      if (firstElement.hasOwnProperty('field_name')) {
        field_name = firstElement.field_name;
      }

      if (!field_name) {
        return '';
      }
      return field_name;
    },

    focusOnTableGroup(groupIndex: string) {
      const field = this.formLayout[groupIndex].rows[0];
      this.focusOnTable(field.name);
    },

    validateAllSectionFields(index: any) {
      if (this.isReadOnly) {
        return;
      }
      const section = this.formLayout[index];
      if (!section.hasOwnProperty('rows')) {
        logInfo('No rows found to validate in this section');
        return;
      }

      for (const fieldDef of section.rows) {
        this.validateField(fieldDef.field_name);
      }
    },

    selectFieldFromNextGroup(e: any) {
      let current_group_el = e.target.closest('[data-group-id]');

      // find first
      if (!current_group_el) {
        current_group_el = document.querySelector('[data-group-id]');
      }

      if (!current_group_el) {
        return;
      }

      const group_index = current_group_el.getAttribute('data-group-id');
      const next_group_index = Number(group_index) + 1;
      this.focusFirstFieldOnGroup(next_group_index);
    },

    validateAndSelectNextInvalidField(selectedwraperId: string) {
      let moveToNextFiled = false;
      let componentType = '';

      for (const group of this.formLayout) {
        for (const subRow of group.rows) {
          let field_name = subRow.field_name;
          let data_field = this.formBuilderModel[field_name];
          if (!data_field) {
            continue;
          }

          if (moveToNextFiled === true) {
            if (subRow.is_readonly == true || subRow.is_hidden == true) {
              continue;
            }

            if (data_field.is_valid == true || data_field.calculation_formula) {
              continue;
            }

            this.focusOnField(field_name);
            moveToNextFiled = false;
            return;
          }

          if (field_name === selectedwraperId) {
            moveToNextFiled = true;
            this.validateField(field_name);
            const parentDiv: HTMLElement | null = $('#' + field_name);
            componentType = this.getComponentType(field_name);

            if (componentType == '') {
              parentDiv!.blur();
            } else {
              const input: HTMLElement | null =
                parentDiv!.querySelector(componentType);
              input!.blur();
            }
          }
        }
      }
    },

    focusOnField(field_name: string, start_timer = true, select_value = false) {
      const parentDiv: HTMLElement | null = $('#' + field_name);

      if (!parentDiv) {
        logError('cannot find field', field_name);
        return;
      }

      // For checkbox or non-input fields
      const componentType = this.getComponentType(field_name);
      if (componentType == '') {
        parentDiv.focus();
        if (start_timer) {
          this.startTimer();
        }
        return;
      }

      // For input fields
      const input: HTMLInputElement | null =
        parentDiv.querySelector(componentType);
      if (!input) {
        logError('cannot find field', componentType);
        return;
      }

      input.click();
      input.focus();
      this.scrollInToViewCenter(input);

      if (select_value) {
        input.select();
      }

      if (start_timer) {
        this.startTimer();
      }
    },

    selectNextField(selectedwraperId: string) {
      let moveToNextFiled = false;
      let componentType = '';

      for (const group of this.formLayout) {
        for (const subRow of group.rows) {
          let field_name = subRow.field_name;
          let data_field = this.formBuilderModel[field_name];
          if (!data_field) {
            continue;
          }

          if (moveToNextFiled === true) {
            if (subRow.is_readonly == true || subRow.is_hidden == true) {
              continue;
            }

            this.focusOnField(field_name);
            moveToNextFiled = false;
            return;
          }

          if (field_name === selectedwraperId) {
            const parentDiv: HTMLElement | null = $('#' + field_name);
            componentType = this.getComponentType(field_name);
            // Getting input value
            const input: HTMLElement | null =
              parentDiv!.querySelector(componentType);
            input!.blur();
            this.validateField(field_name);
            moveToNextFiled = true;
          }
        }
      }
    },

    getNextTabIndex(tab_Index: number): number {
      let found_index = false;
      let next_index = 0;
      for (const [key, value] of Object.entries(this.fields_tabindex_mapping)) {
        const current_index = Number(key);

        if (found_index === true) {
          next_index = current_index;
          break;
        }

        if (tab_Index === current_index) {
          found_index = true;
        }
      }

      const fields = this.fields_tabindex_mapping[next_index];
      if (!fields || !Array.isArray(fields)) {
        return this.getNextTabIndex(next_index);
      }

      return next_index;
    },

    isFieldAvailableToFocus(field_name: string) {
      const field_el: HTMLElement | null = $('#' + field_name);
      if (!field_el) {
        return false;
      }
      return true;
    },

    // same index, field is not valid then move to next field
    getNextTabIndexField(tabIndex: number, field_name: string): string {
      try {
        const fields = this.fields_tabindex_mapping[tabIndex];
        const field_index = fields.indexOf(field_name);

        if (field_index === fields.length - 1) {
          const next_tab_Index = this.getNextTabIndex(tabIndex);
          const first_field = String(
            this.fields_tabindex_mapping[next_tab_Index][0],
          );

          const is_available = this.isFieldAvailableToFocus(first_field);

          if (!is_available) {
            return this.getNextTabIndexField(next_tab_Index, first_field);
          } else {
            return first_field;
          }
        }

        const next_field_index = field_index + 1;
        const next_field_name = String(fields[next_field_index]);
        const is_available = this.isFieldAvailableToFocus(next_field_name);
        if (!is_available) {
          return this.getNextTabIndexField(tabIndex, next_field_name);
        }
        return next_field_name;
      } catch (err) {
        return '';
      }
    },

    findNextField(selectedwraperId: string) {
      const model = this.formBuilderConfigModel[selectedwraperId];
      const tabIndex = Number(model.tabIndex);

      let next_field = this.getNextTabIndexField(tabIndex, selectedwraperId);
      return next_field;
    },

    isFieldTable(field: any) {
      return field.fieldType === 'ExtractedTable';
    },

    focusOnTable(field_name: any) {
      let fieldEl: HTMLElement | null = document!.querySelector(
        '.' + field_name,
      );
      if (!fieldEl) {
        return;
      }
      const event = new CustomEvent('focus_first_row_column', { detail: {} });
      fieldEl.dispatchEvent(event);
    },

    moveToNextFieldEvent(e: any) {
      if (!e.detail) {
        return;
      }
      const next_field = this.findNextField(e.detail);
      if (!next_field) {
        return;
      }
      this.focusOnField(next_field);
    },

    getComponentType(field_name: string) {
      let componentType = '';
      const parentDiv: HTMLElement | null = $('#' + field_name);
      if (!parentDiv) {
        logInfo('NO parentDiv', parentDiv);
        return '';
      }

      componentType = this.getInputType(parentDiv);
      if (componentType == 'checkbox' || componentType == '') {
        return '';
      }
      return componentType;
    },

    validateField(field_name: string) {
      if (!this.formBuilderModel[field_name]) {
        logInfo(
          'validateField formBuilderModel missing field_name',
          field_name,
          this.formBuilderModel[field_name],
        );
        return;
      }

      let fieldDef = this.formBuilderConfigModel[field_name];
      this.formBuilderModel[field_name].color = 'success-border-left';
      this.formBuilderModel[field_name].is_valid = true;
      this.formBuilderModel[field_name].validation_code = null;
      this.formBuilderModel[field_name].validation_message = null;
      this.formBuilderModel[field_name].is_validated = true;

      this.setColor(this.formBuilderModel[field_name], fieldDef);
      this.updateImportJson(field_name);
    },

    getFieldParentDiv(field_name: string) {
      let componentType = '';
      const parentDiv: HTMLElement | null = $('#' + field_name);
      if (!parentDiv) {
        logInfo('NO parentDiv', parentDiv);
        return false;
      }

      componentType = this.getInputType(parentDiv);
      if (componentType == 'checkbox' || componentType == '') {
        logInfo('NO componentType', componentType);
        return false;
      }

      // Getting input value
      const input: HTMLElement | null = parentDiv.querySelector(componentType);
      if (!input) {
        logInfo('NO Element Value', input);
        return false;
      }
      input.blur();
      return true;
    },

    startTimer() {
      const event = new CustomEvent('start_time_spent_on_validation', {});
      document.dispatchEvent(event);
    },

    async focusFirstFieldOnGroup(group_index = 0) {
      await this.$nextTick();

      // find first group to foucs on
      const groupIndex = this.findGroupToFocus(group_index);
      const field_name = this.getFirstFieldOfGroup(String(groupIndex));
      if (field_name) {
        this.focusOnField(field_name, false);
      }
    },

    findGroupToFocus(groupIndex: number): number {
      const group = this.formLayout?.[String(groupIndex)];
      if (!group || !Array.isArray(group.rows)) {
        return groupIndex;
      }

      if (group.rows.length === 0) {
        return this.findGroupToFocus(groupIndex + 1);
      }

      if (group.is_stcky_group) {
        return this.findGroupToFocus(groupIndex + 1);
      }
      const field_name = this.getFirstFieldOfGroup(String(groupIndex));
      if (!field_name) {
        return this.findGroupToFocus(groupIndex + 1);
      }

      return groupIndex;
    },
    keydownEventWrapper(e: any) {
      this.keyDownEvent(e);
    },
  },
  setup() {
    let dataObj: any = [];
    let groupShortCutMap = new Map();

    const form_builder_store = useFormBuilderStore();
    const {
      formBuilderModel,
      formLayout,
      isExtenedPanel,
      isFormBuilderMode,
      formBuilderConfigModel,
      renderComponent,
      docType,
      fieldListToHighlight,
    } = storeToRefs(form_builder_store);
    const {
      getElementWidth,
      prepareLayoutData,
      isFieldHidden,
      getArtikelNummerFields,
      getLayoutTemplate,
    } = form_builder_store;

    const doc_store = useDocumentStore();
    const {
      record,
      lookup_configurations,
      script_response,
      script_api_timestamp,
      get_cached_data_id,
      auto_saving,
      auto_saved_done,
      api_request_id,
    } = storeToRefs(doc_store);
    const {
      saveDocument,
      applyScriptOnDocument,
      updateRecordAfterScript,
      setDataToCache,
      setRecordFromCache,
      updateRequestId,
    } = doc_store;

    const doc_ms_data_lookup_store = useDocMasterDataLookUpStore();
    const {
      model: ms_view_model,
      advance_filters: ms_advance_filters,
      master_lookup_type,
      selected_row: master_data_row,
      populate_row_to_view,
      master_data_fields_map,
    } = storeToRefs(doc_ms_data_lookup_store);
    const { resetMasterDataStore, isContentChanged, isCurrentFieldPrimary } =
      doc_ms_data_lookup_store;

    const field_values_setting_store = useFieldValuesSettingsStore();
    const { populateListsAndValues, addNameToLovList } =
      field_values_setting_store;

    const form_builder_settings_store = useFormBuilderSettingsStore();
    const { isConfirmationBoxDisable } = storeToRefs(
      form_builder_settings_store,
    );

    const doc_lock_store = useDocLockStore();
    const { releaseDocLock } = doc_lock_store;

    const dashboard_store = useDashboardStore();
    const { dashboardFiltersAfterExport } = dashboard_store;

    const settings_store = useSettingStore();
    const { startSettingsFetch } = settings_store;

    return {
      lookup_configurations,
      script_api_timestamp,
      script_response,
      api_request_id,
      updateRecordAfterScript,
      isCurrentFieldPrimary,
      getLayoutTemplate,
      startSettingsFetch,
      addNameToLovList,
      updateRequestId,
      isFieldHidden,
      getArtikelNummerFields,
      dashboardFiltersAfterExport,
      auto_saving,
      auto_saved_done,
      setRecordFromCache,
      setDataToCache,
      saveDocument,
      releaseDocLock,
      resetMasterDataStore,
      applyScriptOnDocument,
      populateListsAndValues,
      get_cached_data_id,
      master_lookup_type,
      ms_advance_filters,
      isContentChanged,
      isConfirmationBoxDisable,
      master_data_fields_map,
      populate_row_to_view,
      master_data_row,
      ms_view_model,
      record,
      apiData: ref(dataObj),
      tableAreasStr: ref(''),
      // model: ref({} as dynamicObj),
      // fieldsDef: ref({} as dynamicObj),
      isSelectedAreaFieldsReady: ref(false),
      is_sep_view: ref(false),
      fuzzyDialog: ref(false),
      selectedRow: ref([]),
      renderKey: 0,
      formBuilderModel,
      formLayout,
      isExtenedPanel,
      isFormBuilderMode,
      formBuilderConfigModel,
      renderComponent,
      docType,
      groupShortCutMap: groupShortCutMap,
      fieldListToHighlight,

      // funcations
      getElementWidth,
      prepareLayoutData,
      is_admin: ref(false),
      master_data_popup_width: ref('700'),
      fields_tabindex_mapping: ref({} as dynamicObj),
      script_loading: ref(false),
    };
  },
});
</script>

